import json, sys, html
sys.path.insert(0, '.')
import data
M = json.load(open('media.json'))
e = html.escape

CSS = """<style>.rbj{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#18212f;font-size:17px;line-height:1.75;max-width:1040px;margin:0 auto;-webkit-font-smoothing:antialiased}.rbj *{box-sizing:border-box}.rbj p{margin:0 0 14px}.rbj a{color:#0b5cad;text-underline-offset:3px}.rbj-hero{padding:32px 24px;border-radius:12px;background:#f4f8ff;border:1px solid #d9e7ff;margin:0 0 28px}.rbj-kicker{font-size:.85rem;font-weight:700;letter-spacing:.02em;color:#0f5b9c;margin:0 0 10px;text-transform:uppercase}.rbj-lead{font-size:1.12rem;line-height:1.7;margin:0 0 16px}.rbj-note{border-radius:10px;padding:14px 18px;background:#fffbea;border:1px solid #f1dc8a;font-size:.95rem;line-height:1.65;margin:16px 0 0}.rbj-nav{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 18px}.rbj-nav a{display:inline-block;padding:6px 14px;border-radius:999px;background:#eef4ff;border:1px solid #cfe0fb;font-size:.92rem;font-weight:600;text-decoration:none;color:#0b4f8a}.rbj-search{width:100%;padding:12px 16px;border:1px solid #cdd8e6;border-radius:10px;font-size:1rem;margin:0 0 8px;background:#fff;color:#18212f}.rbj-count{font-size:.88rem;color:#536170;margin:0 0 8px}.rbj-sec{margin:44px 0}.rbj-sec h2{font-size:1.5rem;line-height:1.35;margin:0 0 10px;font-weight:800;scroll-margin-top:80px}.rbj-intro{color:#3a4656;margin:0 0 18px}.rbj-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px}.rbj-card{border:1px solid #dbe4ef;border-radius:12px;background:#fff;padding:14px;display:flex;flex-direction:column}.rbj-img{display:flex;align-items:center;justify-content:center;height:150px;margin:0 0 10px}.rbj-img img{max-height:150px;max-width:100%;width:auto;height:auto;object-fit:contain;border:0;box-shadow:none}.rbj-code{display:block;font-size:.78rem;font-weight:700;color:#0f5b9c;letter-spacing:.02em}.rbj-jp{display:block;font-size:.92rem;color:#536170;margin:2px 0 4px;line-height:1.5}.rbj-name{font-weight:800;font-size:1.04rem;line-height:1.4;margin:0 0 6px}.rbj-exp{font-size:.95rem;line-height:1.65;margin:0}.rbj-tip{margin:10px 0 0;padding:8px 10px;border-radius:8px;background:#fff1f0;border:1px solid #f6c9c4;font-size:.88rem;line-height:1.55;color:#7c1f15}.rbj-tip b{color:#a1281b}.rbj-steps{padding-left:1.4em;margin:0}.rbj-steps li{margin:0 0 10px}.rbj-src{font-size:.88rem;line-height:1.6;color:#536170;margin:28px 0 0}.rbj-hide{display:none!important}@media(max-width:720px){.rbj{font-size:16px}.rbj-hero{padding:24px 16px}.rbj-sec h2{font-size:1.28rem}.rbj-grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.rbj-card{padding:10px}.rbj-img{height:110px}.rbj-img img{max-height:110px}}</style>"""

total = sum(len(s[3]) for s in data.SECTIONS)
out = [CSS, '<div class="rbj">']
out.append(f'''<section class="rbj-hero"><p class="rbj-kicker">Persiapan ujian SIM 原付 (Gentsuki)</p><p class="rbj-lead">Daftar lengkap <strong>{total} rambu lalu lintas Jepang (道路標識)</strong> dengan gambar resmi dan penjelasan dalam Bahasa Indonesia, dikelompokkan sesuai kategori yang dipakai di ujian tulis 原付.</p><p>Setiap rambu dilengkapi kode resmi, nama Jepang (karena kata inilah yang muncul di soal), dan arti. Kotak merah <b>Ujian 原付</b> berisi poin yang paling sering menjebak.</p><p class="rbj-note">💡 Prioritas belajar: <strong>規制標識 (larangan)</strong>, lalu <strong>補助標識 (papan tambahan)</strong> dan <strong>指示標識</strong>. Rambu peringatan kuning cukup dikenali artinya.</p></section>''')
out.append('<nav class="rbj-nav">' + ''.join(f'<a href="#{s[0]}">{e(s[1].split(" — ")[1])} ({len(s[3])})</a>' for s in data.SECTIONS) + '</nav>')
out.append('<input class="rbj-search" id="rbj-q" type="search" placeholder="Cari rambu… (mis. parkir, 原付, 徐行, 323)" aria-label="Cari rambu"><p class="rbj-count" id="rbj-c"></p>')
for sid, title, intro, rows in data.SECTIONS:
    out.append(f'<section class="rbj-sec" id="{sid}"><h2>{e(title)}</h2><p class="rbj-intro">{intro}</p><div class="rbj-grid">')
    for key, code, jp, idn, exp, tip in rows:
        m = M[key]
        alt = e(f'Rambu Jepang {code} {jp} – {idn}')
        tip_html = f'<p class="rbj-tip"><b>Ujian 原付:</b> {tip}</p>' if tip else ''
        out.append(f'<div class="rbj-card"><div class="rbj-img"><img src="{m["url"]}" alt="{alt}" width="{m["w"]}" height="{m["h"]}" loading="lazy" decoding="async"></div><div class="rbj-code">({e(code)})</div><div class="rbj-jp" lang="ja">{e(jp)}</div><p class="rbj-name">{e(idn)}</p><p class="rbj-exp">{exp}</p>{tip_html}</div>')
    out.append('</div></section>')
out.append('''<section class="rbj-sec"><h2>Cara cepat menghafal rambu</h2><ol class="rbj-steps"><li><strong>Lihat warna & bentuk dulu.</strong> Kuning belah ketupat = peringatan. Lingkaran merah = larangan. Biru = kewajiban/boleh. Segitiga merah terbalik = 止まれ / 徐行. Papan putih di bawah = 補助標識.</li><li><strong>Hafalkan rambu yang menyangkut 原付:</strong> 304 (原付 boleh), 307 (原付 dilarang), 323 (原付 tetap 30 km/h), 325 (jalan tol, 原付 dilarang), 327の4 (lajur bus, 原付 boleh), 327の8 dan 327の9 (cara belok kanan).</li><li><strong>Perhatikan pasangan yang mirip:</strong> 一方通行 vs 左折可, 最高速度 vs 最低速度, 学校あり (kuning) vs 横断歩道 (biru), 車線数減少 vs 幅員減少, 始まり (→) vs 終わり (←).</li><li><strong>Baca papan tambahan.</strong> 「~を除く」 = tidak berlaku untuk kendaraan/hari itu. 「8-20」 = hanya jam 8–20.</li></ol></section>''')
out.append('<p class="rbj-src">Sumber gambar: 国土交通省 道路局「道路標識一覧」 (Kementerian Pertanahan, Infrastruktur, Transportasi dan Pariwisata Jepang). Penjelasan disusun berdasarkan 道路交通法 dan materi ujian 原付. Aturan bisa berubah; untuk kepastian, cek situs kepolisian prefektur Anda.</p>')
out.append('''<script>(function(){var q=document.getElementById('rbj-q'),c=document.getElementById('rbj-c');if(!q)return;var cards=[].slice.call(document.querySelectorAll('.rbj-card')),secs=[].slice.call(document.querySelectorAll('.rbj-sec[id]'));cards.forEach(function(el){el._t=el.textContent.toLowerCase()});function f(){var v=q.value.trim().toLowerCase(),n=0;cards.forEach(function(el){var ok=!v||el._t.indexOf(v)>-1;el.classList.toggle('rbj-hide',!ok);if(ok)n++});secs.forEach(function(s){s.classList.toggle('rbj-hide',v&&!s.querySelector('.rbj-card:not(.rbj-hide)'))});c.textContent=v?n+' rambu ditemukan':''}q.addEventListener('input',f)})();</script>''')
out.append('</div>')
open('page.html', 'w').write(''.join(out))
print(len(''.join(out)))
